(()=>{'use strict';
const $=id=>document.getElementById(id),M=window.DashboardModel,sessions=structuredClone(window.MOCK_SESSIONS),expanded=new Set(),nodes=new Map(),disconnectedSessions=new Set(),laneScrollPositions=new Map();
let view='gallery',thumbnailSize='m',inspectorExpanded=false,expandedLayoutSnapshot=null,scope={},query='',activity='all',currentId=null,currentPane=null,inspectOrder=[],lastFocus=null,dragId=null,toastTimer,treeFocus=null,dragScrollFrame=0,dragScrollTarget=null,dragScrollSpeed=0;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="icon" aria-hidden="true" focusable="false"><use href="#i-${name}"/></svg>`;
for(const el of document.querySelectorAll('svg.icon')){el.setAttribute('aria-hidden','true');el.setAttribute('focusable','false')}
const list=()=>M.visible(sessions,{scope,query,activity:'all'}).filter(s=>activity==='all'||observationFor(M.primary(s),s.id).activity===activity);
const workflowOptions=(selected)=>M.workflows.map(w=>`<option value="${w.id}"${w.id===selected?' selected':''}>${w.label}</option>`).join('');
function observationFor(pane,sessionId){return disconnectedSessions.has(sessionId)?{...pane.observation,activity:'unknown',confidence:'unknown',freshness:'stale',evidence:'Mock disconnected. The last capture is cached; current activity is unknown.'}:pane.observation}
function observed(pane,details=false,sessionId=null){const o=observationFor(pane,sessionId),a=M.activities[o.activity];return `<span class="observed ${o.activity}">${icon(a.icon)}<span>${a.label}</span>${o.freshness==='stale'?'<span class="stale">STALE</span>':''}</span>${details?`<div class="observation-meta"><span>${o.confidence==='unknown'?'Confidence unknown':o.confidence+' confidence'} · ${o.freshness==='stale'?'stale':'fresh'}</span><span>${escape(o.age.replace('ago','old'))}</span></div>`:''}`}
function capture(pane){return pane.lines.map(t=>`<span class="capture-line ${t.startsWith('✓')?'good':t.startsWith('$')||t.includes('▍')||t.includes('[y/n]')?'prompt':t.startsWith('[')?'dim':''}">${escape(t)||' '}</span>`).join('')}
function card(s){const p=M.primary(s);return `<article class="session-card" data-session-id="${s.id}"${view==='board'?' draggable="true"':''}><button class="card-preview" data-open="${s.id}" aria-label="Inspect ${escape(s.name)} on ${escape(s.device)}"><span class="capture-chrome"><span>${escape(p.agent==='None'?'shell':p.agent)} · ${escape(p.id)}</span><span class="pane-count">${s.panes.length} ${s.panes.length===1?'pane':'panes'}</span></span><span class="capture">${capture(p)}</span><span class="card-open-cue">Inspect session</span></button><div class="card-info"><div class="card-heading"><button class="card-title" data-open="${s.id}" title="${escape(s.title)}"><span>${escape(s.title)}</span></button>${view==='board'?`<span class="drag-handle" aria-hidden="true" title="Drag to move workflow">${icon('grip')}</span>`:''}</div><p class="card-origin" title="${escape(s.device+' / '+s.project+' / '+s.name)}">${escape(s.device)} / ${escape(s.project)}</p><div title="Observed primary pane: ${escape(observationFor(p,s.id).evidence)}">${observed(p,true,s.id)}</div></div><label class="card-workflow"><span class="field-label">Manual workflow</span><select data-move="${s.id}" data-workflow="${s.workflow}" aria-label="Manual workflow for ${escape(s.name)}">${workflowOptions(s.workflow)}</select></label></article>`}
function renderCards(){renderHome();const target=$('session-surface'),top=target.scrollTop,left=target.scrollLeft,shown=list();for(const scroller of target.querySelectorAll('[data-scroll-lane]'))laneScrollPositions.set(scroller.dataset.scrollLane,scroller.scrollTop);$('workspace').classList.toggle('board-view',view==='board');target.classList.toggle('compact',view==='gallery'&&thumbnailSize==='s');target.classList.toggle('large',view==='gallery'&&thumbnailSize==='l');target.dataset.thumbnailSize=thumbnailSize;target.innerHTML=shown.length?(view==='gallery'?`<div class="gallery">${shown.map(card).join('')}</div>`:`<div class="board" aria-label="Manual workflow board">${M.workflows.map(w=>{const children=shown.filter(s=>s.workflow===w.id);return `<section class="board-lane" data-drop="${w.id}" aria-label="${w.label} workflow"><header class="lane-header" data-lane="${w.id}"><span class="lane-marker" aria-hidden="true"></span><h2>${w.label}</h2><span class="count">${children.length}</span></header><div class="lane-cards" data-scroll-lane="${w.id}" tabindex="0" role="region" aria-label="${w.label} session cards">${children.map(card).join('')||'<div class="empty-lane">Drop a session here<br>or use its workflow menu</div>'}</div></section>`}).join('')}</div>`):'<div class="empty-results"><h2>No matching sessions</h2><p>Try another project, activity or search.</p><button id="clear-filters">Show all sessions</button></div>';target.scrollTop=top;target.scrollLeft=left;for(const scroller of target.querySelectorAll('[data-scroll-lane]'))scroller.scrollTop=laneScrollPositions.get(scroller.dataset.scrollLane)||0;$('session-count').textContent=shown.length;$('surface-summary').textContent=`${shown.length} of ${sessions.length} synthetic sessions · ${view==='gallery'?'captured pane previews':'manual workflow'}`;
$('scope-title').firstChild.textContent=scope.session?(sessions.find(s=>s.id===scope.session)?.name||'Session')+' ':scope.project?scope.project+' ':scope.device?scope.device+' ':'Home ';$('breadcrumb').textContent=[scope.device,scope.project].filter(Boolean).join(' / ')||'All devices';
}
function renderHome(){const devices=[...new Set(sessions.map(s=>s.device))];$('home-health').innerHTML=devices.map(device=>{const own=sessions.filter(s=>s.device===device),panes=own.flatMap(s=>s.panes.map(p=>observationFor(p,s.id))),stale=panes.filter(p=>p.freshness==='stale').length,waiting=panes.filter(p=>p.activity==='waiting').length,disconnected=own.filter(s=>disconnectedSessions.has(s.id)).length;return `<button class="device-summary${scope.device===device?' selected':''}" data-device-scope="${escape(device)}" aria-pressed="${scope.device===device}"><span class="device-summary-title">${icon('device')}<strong>${escape(device)}</strong><span class="health-indicator ${stale||disconnected?'attention':'fresh'}">${disconnected?'Cached':stale?'Check freshness':'Fresh captures'}</span></span><span class="device-summary-meta">${own.length} sessions · ${new Set(own.map(s=>s.project)).size} projects · ${waiting} waiting</span><span class="device-summary-age">${stale} stale panes · ${disconnected} mock disconnected</span></button>`}).join('')}
$('home-health').onclick=event=>{const button=event.target.closest('[data-device-scope]');if(!button)return;scope={device:button.dataset.deviceScope};renderTree();renderCards()};
function makeTree(){nodes.clear();const devices=[...new Set(sessions.map(s=>s.device))];let roots=[];devices.forEach((device,di)=>{const id='device-'+di,node={id,label:device,icon:'device',depth:0,scope:{device},children:[],parent:null};nodes.set(id,node);expanded.add(id);[...new Set(sessions.filter(s=>s.device===device).map(s=>s.project))].forEach((project,pi)=>{const pid=id+'-project-'+pi,p={id:pid,label:project,icon:'folder',depth:1,scope:{device,project},children:[],parent:id};nodes.set(pid,p);node.children.push(p);expanded.add(pid);for(const s of sessions.filter(s=>s.device===device&&s.project===project)){const sid='session-'+s.id,sn={id:sid,label:s.name,icon:'session',depth:2,scope:{device,project,session:s.id},children:[],parent:pid,session:s.id};nodes.set(sid,sn);p.children.push(sn);for(const pane of s.panes){const q={id:sid+'-pane-'+pane.id,label:pane.id+' · '+pane.name,icon:'terminal',depth:3,scope:sn.scope,children:[],parent:sid,session:s.id,pane:pane.id};nodes.set(q.id,q);sn.children.push(q)}}});roots.push(node)});return roots}
const roots=makeTree();
function isSelected(n){return JSON.stringify(n.scope)===JSON.stringify(scope)&&!n.pane}
function renderTree(){
 function draw(n,last=false){
  const open=expanded.has(n.id),selected=isSelected(n),current=n.session===currentId&&n.pane===currentPane,groupId='tree-group-'+n.id;
  return `<li class="tree-item${last?' is-last':''}" data-depth="${n.depth}" role="none">${n.depth?'<span class="tree-vline" aria-hidden="true"></span>':''}<div class="tree-row${selected?' is-selected':''}${current?' is-current':''}" data-depth="${n.depth}">${n.depth?'<span class="tree-elbow" aria-hidden="true"></span>':''}<button class="tree-label" role="treeitem" aria-level="${n.depth+1}" aria-selected="${selected||current}" ${n.children.length?`aria-expanded="${open}" aria-owns="${groupId}"`:''} data-node="${n.id}" ${n.parent?`data-parent="${n.parent}"`:''} tabindex="${treeFocus===n.id?'0':'-1'}" title="${escape(n.label)}">${icon(n.icon)}<span class="label">${escape(n.label)}</span></button>${n.children.length?`<button class="tree-twisty" data-expand="${n.id}" aria-expanded="${open}" aria-controls="${groupId}" aria-label="${open?'Collapse':'Expand'} ${escape(n.label)}" title="${open?'Collapse':'Expand'} ${escape(n.label)}" tabindex="-1">${icon('chevron')}</button>`:'<span class="tree-toggle-spacer" aria-hidden="true"></span>'}</div>${n.children.length?`<ul id="${groupId}" role="group"${open?'':' hidden'}>${n.children.map((child,i)=>draw(child,i===n.children.length-1)).join('')}</ul>`:''}</li>`
 }
 if(!treeFocus)treeFocus=roots[0].id;
 $('tree').innerHTML=`<ul class="tree-list" role="tree" aria-label="Devices, projects, sessions and panes">${roots.map((n,i)=>draw(n,i===roots.length-1)).join('')}</ul>`;
 $('all-sessions').classList.toggle('selected',Object.keys(scope).length===0)
}
function selectNode(id){const n=nodes.get(id);if(!n)return;treeFocus=id;scope={...n.scope};renderTree();renderCards();if(n.pane)openInspector(n.session,n.pane);closeTree()}
function focusNode(id){treeFocus=id;for(const el of document.querySelectorAll('[data-node]'))el.tabIndex=el.dataset.node===id?0:-1;document.querySelector(`[data-node="${CSS.escape(id)}"]`)?.focus()}
function announce(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500)}
function moveSession(id,workflow){const result=M.move(sessions,id,workflow);if(result.previous===workflow)return;const label=M.workflows.find(w=>w.id===workflow).label;renderCards();if(currentId===id)$('inspector-workflow').value=workflow;announce(`${result.session.name} moved to ${label}. Dashboard label only; observed activity is unchanged.`)}
function setView(next){view=next;$('view-gallery').setAttribute('aria-pressed',String(view==='gallery'));$('view-board').setAttribute('aria-pressed',String(view==='board'));$('gallery-sizes').hidden=false;$('view-description').textContent=view==='gallery'?'Scan every capture, then open a session to inspect its panes.':'Organize sessions yourself. Drag a card, or choose its manual workflow.';$('session-surface').scrollTop=0;$('session-surface').scrollLeft=0;renderCards()}
function updateInspectorMeta(){const s=sessions.find(s=>s.id===currentId),pane=s.panes.find(p=>p.id===currentPane)||M.primary(s);currentPane=pane.id;$('inspector-title').textContent=s.name;$('inspector-breadcrumb').textContent=s.device+' / '+s.project;$('inspector-activity').innerHTML=observed(pane,true,s.id);$('inspector-evidence').textContent=observationFor(pane,s.id).evidence;$('inspector-workflow').innerHTML=workflowOptions(s.workflow);$('pane-tabs').innerHTML=s.panes.map(p=>`<button data-pane="${p.id}" aria-pressed="${p.id===currentPane}">${icon('terminal')}${escape(p.id+' · '+p.name)}</button>`).join('');const at=inspectOrder.indexOf(s.id);$('inspector-position').textContent=(at+1)+' / '+inspectOrder.length;$('inspector-prev').disabled=at<=0;$('inspector-next').disabled=at>=inspectOrder.length-1;for(const n of nodes.values())if(n.session===s.id){expanded.add(n.parent);expanded.add('session-'+s.id)}renderTree()}
function consoleLayout(){try{return $('console-frame').contentWindow?.consoleLayout}catch{return null}}
function setInspectorExpanded(next){
 if(next===inspectorExpanded)return;
 const layout=consoleLayout(),now=layout?.captureLayout?.();
 if(next)expandedLayoutSnapshot=now||null;
 let restore=now;
 if(!next&&now&&expandedLayoutSnapshot&&now.scrollRevision===expandedLayoutSnapshot.scrollRevision)restore={...now,top:expandedLayoutSnapshot.top,following:expandedLayoutSnapshot.following};
 inspectorExpanded=next;
 $('inspector').classList.toggle('is-expanded',next);
 const button=$('inspector-expand'),label=next?'Restore detail size':'Expand detail to full window';
 button.setAttribute('aria-pressed',String(next));button.setAttribute('aria-label',label);button.title=label;
 button.querySelector('use').setAttribute('href',next?'#i-restore':'#i-expand');button.querySelector('span').textContent=next?'Restore size':'Expand to full';
 $('inspector-escape-hint').textContent=next?'Escape to restore size':'Escape to return';
 layout?.restoreLayout?.(restore);
 if(!next)expandedLayoutSnapshot=null;
}
function handleInspectorEscape(){if(consoleLayout()?.isComposing?.()||consoleLayout()?.ownsEscape?.())return;if(inspectorExpanded)setInspectorExpanded(false);else closeInspector()}
function openInspector(id,paneId){let paneController=null;try{if($('inspector').open&&currentId===id)paneController=$('console-frame').contentWindow?.mockInput}catch{}expandedLayoutSnapshot=null;if(!$('inspector').open){setInspectorExpanded(false);lastFocus=document.activeElement;inspectOrder=list().map(s=>s.id);if(!inspectOrder.includes(id))inspectOrder=sessions.map(s=>s.id);$('inspector').showModal()}currentId=id;currentPane=paneId||M.primary(sessions.find(s=>s.id===id)).id;updateInspectorMeta();if(paneController?.selectPane){paneController.selectPane(currentPane);const actual=paneController.state?.().target;if(actual&&actual!==currentPane){currentPane=actual;updateInspectorMeta()}}else $('console-frame').src='console.html?embed=1&session='+encodeURIComponent(id)+'&pane='+encodeURIComponent(currentPane)+'&connected='+(disconnectedSessions.has(id)?'0':'1');$('inspector-close').focus({preventScroll:true})}
function closeInspector(){setInspectorExpanded(false);expandedLayoutSnapshot=null;$('inspector').close();$('console-frame').src='about:blank';currentId=null;currentPane=null;renderTree();if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});else $('view-'+view).focus({preventScroll:true})}
function stepInspector(amount){const i=inspectOrder.indexOf(currentId),id=inspectOrder[i+amount];if(id)openInspector(id)}
function showTree(){document.body.classList.add('tree-open');$('tree-scrim').hidden=false;$('tree-toggle').setAttribute('aria-expanded','true');$('tree-close').focus()}
function closeTree(){const was=document.body.classList.contains('tree-open');document.body.classList.remove('tree-open');$('tree-scrim').hidden=true;$('tree-toggle').setAttribute('aria-expanded','false');if(was&&!$('inspector').open)$('tree-toggle').focus()}
$('tree-toggle').onclick=showTree;$('tree-close').onclick=closeTree;$('tree-scrim').onclick=closeTree;
$('all-sessions').onclick=()=>{scope={};renderTree();renderCards();closeTree()};
$('tree').addEventListener('click',e=>{const expand=e.target.closest('[data-expand]');if(expand){const id=expand.dataset.expand;expanded.has(id)?expanded.delete(id):expanded.add(id);renderTree();focusNode(id);return}const row=e.target.closest('[data-node]');if(row)selectNode(row.dataset.node)});
$('tree').addEventListener('keydown',e=>{const row=e.target.closest('[data-node]');if(!row)return;const n=nodes.get(row.dataset.node),visible=[...document.querySelectorAll('[data-node]')].filter(el=>!el.closest('[hidden]')),i=visible.indexOf(row);let next=null;if(e.key==='ArrowDown')next=visible[Math.min(i+1,visible.length-1)];else if(e.key==='ArrowUp')next=visible[Math.max(0,i-1)];else if(e.key==='Home')next=visible[0];else if(e.key==='End')next=visible.at(-1);else if(e.key==='ArrowRight'){if(n.children.length&&!expanded.has(n.id)){expanded.add(n.id);renderTree();next=document.querySelector(`[data-node="${CSS.escape(n.id)}"]`)}else if(n.children.length)next=document.querySelector(`[data-node="${CSS.escape(n.children[0].id)}"]`)}else if(e.key==='ArrowLeft'){if(n.children.length&&expanded.has(n.id)){expanded.delete(n.id);renderTree();next=document.querySelector(`[data-node="${CSS.escape(n.id)}"]`)}else if(n.parent)next=document.querySelector(`[data-node="${CSS.escape(n.parent)}"]`)}else if(e.key==='Enter'&&n.session){e.preventDefault();openInspector(n.session,n.pane);return}else return;e.preventDefault();if(next)focusNode(next.dataset.node)});
$('search').addEventListener('input',()=>{query=$('search').value;renderCards()});$('activity-filter').onchange=()=>{activity=$('activity-filter').value;renderCards()};
$('view-gallery').onclick=()=>setView('gallery');$('view-board').onclick=()=>setView('board');$('gallery-sizes').onclick=e=>{const button=e.target.closest('[data-size]');if(!button)return;thumbnailSize=button.dataset.size;for(const b of document.querySelectorAll('[data-size]'))b.setAttribute('aria-pressed',String(b.dataset.size===thumbnailSize));renderCards()};
$('session-surface').addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)openInspector(b.dataset.open);if(e.target.closest('#clear-filters')){scope={};query='';activity='all';$('search').value='';$('activity-filter').value='all';renderTree();renderCards()}});
$('session-surface').addEventListener('change',e=>{if(e.target.matches('[data-move]')){const id=e.target.dataset.move;moveSession(id,e.target.value);const moved=document.querySelector(`[data-move="${id}"]`);moved?.focus({preventScroll:true});moved?.scrollIntoView?.({block:'nearest',inline:'nearest'})}});
function stopDragScroll(){if(dragScrollFrame)cancelAnimationFrame(dragScrollFrame);dragScrollFrame=0;dragScrollTarget=null;dragScrollSpeed=0}
function tickDragScroll(){dragScrollFrame=0;if(!dragId||!dragScrollTarget?.isConnected||!dragScrollSpeed)return;const previous=dragScrollTarget.scrollTop;dragScrollTarget.scrollTop+=dragScrollSpeed;if(dragScrollTarget.scrollTop!==previous)dragScrollFrame=requestAnimationFrame(tickDragScroll)}
function updateDragScroll(lane,event){if(!Number.isFinite(event.clientY)){stopDragScroll();return}const target=lane.querySelector('.lane-cards'),bounds=target.getBoundingClientRect();const speed=event.clientY<bounds.top+44?-12:event.clientY>bounds.bottom-44?12:0;if(!speed){stopDragScroll();return}dragScrollTarget=target;dragScrollSpeed=speed;if(!dragScrollFrame)dragScrollFrame=requestAnimationFrame(tickDragScroll)}
$('session-surface').addEventListener('dragstart',e=>{const card=e.target.closest('[data-session-id]');if(view!=='board'||!card||e.target.closest('select')){e.preventDefault();return}dragId=card.dataset.sessionId;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragId);card.classList.add('dragging')});
$('session-surface').addEventListener('dragover',e=>{const lane=e.target.closest('[data-drop]');if(!lane||!dragId)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-target').forEach(n=>n.classList.remove('drop-target'));lane.classList.add('drop-target');updateDragScroll(lane,e)});
$('session-surface').addEventListener('drop',e=>{const lane=e.target.closest('[data-drop]');if(!lane||!dragId)return;e.preventDefault();stopDragScroll();const id=dragId;dragId=null;moveSession(id,lane.dataset.drop);document.querySelectorAll('.drop-target,.dragging').forEach(n=>n.classList.remove('drop-target','dragging'))});
$('session-surface').addEventListener('dragend',()=>{stopDragScroll();dragId=null;document.querySelectorAll('.drop-target,.dragging').forEach(n=>n.classList.remove('drop-target','dragging'))});
$('session-surface').addEventListener('dragleave',e=>{if(!e.relatedTarget||!$('session-surface').contains(e.relatedTarget))stopDragScroll()});
$('inspector-close').onclick=closeInspector;$('inspector').addEventListener('cancel',e=>{e.preventDefault();handleInspectorEscape()});$('inspector-expand').addEventListener('pointerdown',e=>{if(document.activeElement===$('console-frame'))e.preventDefault()});$('inspector-expand').onclick=()=>setInspectorExpanded(!inspectorExpanded);$('inspector-prev').onclick=()=>stepInspector(-1);$('inspector-next').onclick=()=>stepInspector(1);$('inspector-workflow').onchange=()=>moveSession(currentId,$('inspector-workflow').value);$('pane-tabs').onclick=e=>{const b=e.target.closest('[data-pane]');if(b&&b.dataset.pane!==currentPane)openInspector(currentId,b.dataset.pane)};
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('console-frame').contentWindow)return;if(e.data?.type==='mock-inspector-escape')handleInspectorEscape();if(e.data?.type==='mock-connection-state'&&e.data.session===currentId&&typeof e.data.connected==='boolean'){e.data.connected?disconnectedSessions.delete(currentId):disconnectedSessions.add(currentId);updateInspectorMeta();renderCards();}if(e.data?.type==='mock-pane-change'&&e.data.session===currentId){const s=sessions.find(s=>s.id===currentId);if(s.panes.some(p=>p.id===e.data.pane)){currentPane=e.data.pane;updateInspectorMeta()}}});
document.addEventListener('keydown',e=>{if(e.key!=='Escape'||e.isComposing||e.keyCode===229||e.defaultPrevented)return;if(dragId){stopDragScroll();dragId=null;document.querySelectorAll('.drop-target,.dragging').forEach(n=>n.classList.remove('drop-target','dragging'));e.preventDefault();return}if($('inspector').open){e.preventDefault();handleInspectorEscape()}else if(document.body.classList.contains('tree-open'))closeTree()});
renderTree();renderCards();
})();
